<template>
  <section class="contact-list">
    <header><h2>{{ $t('expertWorkspace.customerAccess') }}</h2><label class="search"><span aria-hidden="true">⌕</span><input v-model="search" type="search" :placeholder="$t('expertWorkspace.search')" :aria-label="$t('expertWorkspace.search')" /></label><div class="filters" :aria-label="$t('expertWorkspace.customerAccess')"><button v-for="item in filters" :key="item" type="button" :aria-pressed="filter === item" @click="filter = item">{{ $t('expertWorkspace.' + item) }}<span>{{ count(item) }}</span></button></div></header>
    <div class="contact-rows"><p v-if="!rows.length" class="empty" role="status">{{ $t(search ? 'expertWorkspace.noMatches' : 'expertWorkspace.noRequests') }}</p><div v-for="request in rows" :key="request.request_id" class="contact" :class="{ selected: selectedId === request.request_id }"><button type="button" class="contact-main" :aria-pressed="selectedId === request.request_id" :disabled="busy || request.status === 'queued'" @click="$emit('select', request)"><span class="avatar" aria-hidden="true">{{ title(request).slice(0,1) }}</span><span class="contact-copy"><strong>{{ title(request) }}</strong><small :title="request.request_id">{{ request.request_id }}</small><span class="contact-status"><span :class="{ waiting: request.status === 'queued' }">{{ $t('support.' + request.status) }}</span><time>{{ shortDate(request.requested_at) }}</time></span></span></button><button v-if="request.status === 'queued'" type="button" class="claim" :disabled="!accepting || busy" @click="$emit('claim', request)">{{ $t('support.claim') }}</button></div></div>
    <footer><span>{{ $t('expertWorkspace.queueHint') }}</span><button type="button" :disabled="refreshing" :aria-label="$t('expertWorkspace.refreshQueue')" @click="$emit('refresh')">↻ {{ $t('support.refresh') }}</button></footer>
  </section>
</template>
<script>
export default {
  name:'ExpertContactList', props:{ assigned:{type:Array,default:()=>[]}, queue:{type:Array,default:()=>[]}, titles:{type:Object,default:()=>({})}, selectedId:{type:String,default:''}, accepting:Boolean, busy:Boolean, refreshing:Boolean }, emits:['select','claim','refresh'], data:()=>({ search:'', filter:'all', filters:['all','waiting','active','history'] }),
  computed:{ requests(){ const unique=new Map(); for(const request of [...this.assigned,...this.queue]) if(!unique.has(request.request_id)) unique.set(request.request_id,request); return [...unique.values()]; }, rows(){ const query=this.search.trim().toLocaleLowerCase(); return this.requests.filter(request=>this.matches(request,this.filter)&&[this.title(request),request.request_id,request.conversation_id].join(' ').toLocaleLowerCase().includes(query)); } },
  methods:{ title(request){ return this.titles[request.conversation_id] || this.$t('support.consultation'); }, matches(request,filter){ return filter==='all'||(filter==='waiting'?request.status==='queued':filter==='active'?request.status==='active':!['active','queued'].includes(request.status)); }, count(filter){ return this.requests.filter(request=>this.matches(request,filter)).length; }, shortDate(value){ if(!value)return ''; const date=new Date(value); return Number.isNaN(date.getTime())?'':date.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}); } },
};
</script>
<style scoped>
.contact-list { display:flex; flex-direction:column; height:100%; min-height:0; }.contact-list header { padding:20px 14px 0; flex:none; }.contact-list h2 { font-size:20px; margin:0 0 18px; }.search { display:flex; align-items:center; gap:7px; border:1px solid #d9e5e0; border-radius:8px; padding:0 10px; }.search span { color:#6c817c; font-size:24px; }.search input { background:transparent; border:0; outline:0; min-width:0; width:100%; height:42px; font:inherit; color:#173b37; font-size:12px; }.search:focus-within { outline:2px solid #52b8ae; }.filters { display:flex; margin-top:12px; border-bottom:1px solid #e2ebe7; }.filters button { flex:1; min-width:0; padding:12px 0; background:none; border:0; border-bottom:3px solid transparent; color:#6c817c; font-size:12px; }.filters button span { display:block; font-size:10px; margin-top:4px; }.filters button[aria-pressed=true] { color:#087f7b; border-bottom-color:#087f7b; font-weight:650; }.contact-rows { flex:1; min-height:0; overflow:auto; overscroll-behavior:contain; }.contact { position:relative; border-left:3px solid transparent; border-bottom:1px solid #e7eeea; padding:0 11px; }.contact.selected { background:#e1f3ed; border-left-color:#087f7b; }.contact-main { display:flex; align-items:center; gap:9px; width:100%; text-align:left; padding:18px 0; background:transparent; border:0; color:#173b37; }.contact-main:disabled { opacity:1; }.contact-copy { display:grid; gap:6px; flex:1; min-width:0; }.contact-copy strong,.contact-copy small { white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }.contact-copy strong { font-size:14px; }.contact-copy small { font-size:10px; color:#6c817c; }.avatar { width:40px; height:40px; border-radius:50%; display:flex; align-items:center; justify-content:center; background:#d3eee7; color:#087f7b; font-size:18px; flex:none; }.contact-status { display:flex; justify-content:space-between; gap:5px; font-size:11px; color:#6c817c; }.contact-status .waiting { color:#087f7b; }.contact-status time { font-size:10px; }.claim { width:100%; margin:-5px 0 12px; border:1px solid #b8d8ce; border-radius:6px; padding:7px; background:#edf8f4; color:#087f7b; }.empty { padding:28px 16px; font-size:13px; color:#6c817c; line-height:1.8; text-align:center; }footer { border-top:1px solid #e7eeea; padding:14px; display:grid; gap:10px; color:#6c817c; font-size:11px; }footer button { border:1px solid #d9e5e0; padding:9px; border-radius:6px; color:#087f7b; background:white; }button { font:inherit; cursor:pointer; }button:disabled { cursor:not-allowed; opacity:.5; }button:focus-visible { outline:3px solid #52b8ae; outline-offset:2px; }
</style>
